const rojas = [], naranjas = [], verdes = [], grises = [];

for (const item of $input.all()) {
  const nov = item.json;
  const fechaSolucion = (nov['Fecha estimada de solución (Solo Mantenimiento)'] || '').trim();

  // Si no hay fecha, va a GRIS pase lo que pase
  if (fechaSolucion === '') {
    grises.push(nov);
    continue;
  }

  const semaforo = (nov['Semaforo (automatico)'] || '').toLowerCase().trim();
  if (semaforo === 'rojo') {
    rojas.push(nov);
  } else if (semaforo === 'naranja') {
    naranjas.push(nov);
  } else {
    verdes.push(nov);
  }
}

const formatear = (n) => {
  return `- Máquina: ${n.Maquina || 'N/A'}
  Responsable: ${n['Quien creó la novedad (Solo nombre)'] || 'No asignado'}
  Fecha creación: ${n['Fecha de creacion (automatico)'] || 'N/A'}
  Fecha est. solución: ${n['Fecha estimada de solución (Solo Mantenimiento)'] || 'No definida'}
  Observaciones: ${n['Observaciones respecto a la novedad (Obligatorio)'] || 'Sin observaciones'}
  ¿Falta repuesto?: ${n['¿Falta repuesto / s? ¿Cuales? (Mantenimiento)'] || 'No especificado'}`;
};

let texto = '';

if (rojas.length > 0) {
  texto += '🚨 NOVEDADES CRÍTICAS (ROJO)\n\n';
  rojas.forEach(n => { texto += formatear(n) + '\n\n'; });
}

if (naranjas.length > 0) {
  texto += '⚠️ NOVEDADES PRÓXIMAS A VENCER (NARANJA)\n\n';
  naranjas.forEach(n => { texto += formatear(n) + '\n\n'; });
}

if (grises.length > 0) {
  texto += '⚪ NOVEDADES SIN FECHA DE SOLUCIÓN (GRIS)\n\n';
  grises.forEach(n => { texto += formatear(n) + '\n\n'; });
}

if (verdes.length > 0) {
  texto += '✅ NOVEDADES EN TIEMPO (VERDE)\n\n';
  verdes.forEach(n => { texto += formatear(n) + '\n\n'; });
}

if (texto === '') {
  texto = 'No hay novedades registradas en este período.';
}

// ← Esta es la línea que faltaba
return [{ json: { prompt: texto } }];

const raw =
  $input.first().json.output ??
  $input.first().json.text ??
  $input.first().json.respuesta ??
  '';

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function cleanMarkdown(md) {
  let text = String(md || '')
    .replace(/\uFEFF/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/\t/g, '  ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const wrapped = text.match(/^```(?:markdown|md)?\s*([\s\S]*?)\s*```$/i);
  if (wrapped) {
    text = wrapped[1].trim();
  }
  text = text.replace(/^```(?:markdown|md)?\s*$/gim, '');
  text = text.replace(/^```\s*$/gim, '');
  return text.trim();
}

function inlineFormat(text) {
  let s = escapeHtml(text);
  // Links
  s = s.replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
    '<a href="$2" target="_blank" style="color:#0d6efd;text-decoration:none;">$1</a>'
  );
  // Inline code
  s = s.replace(
    /`([^`]+)`/g,
    '<code style="background:#eef2f7;padding:2px 6px;border-radius:6px;font-family:Consolas,monospace;font-size:13px;">$1</code>'
  );
  // Bold
  s = s.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  // Italic
  s = s.replace(/(^|[^*])\*(?!\s)([^*]+?)\*(?!\*)/g, '$1<em>$2</em>');
  // Badges de color
  s = s.replace(
    /\bROJO\b/gi,
    '<span style="display:inline-block;background:#dc3545;color:#fff;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:700;">ROJO</span>'
  );
  s = s.replace(
    /\bNARANJA\b/gi,
    '<span style="display:inline-block;background:#fd7e14;color:#fff;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:700;">NARANJA</span>'
  );
  s = s.replace(
    /\bVERDE\b/gi,
    '<span style="display:inline-block;background:#28a745;color:#fff;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:700;">VERDE</span>'
  );
  s = s.replace(
    /\bGRIS\b/gi,
    '<span style="display:inline-block;background:#6c757d;color:#fff;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:700;">GRIS</span>'
  );
  return s;
}

function buildCallout(title, body, color = '#0d6efd') {
  return `
    <div style="
      border-left:5px solid ${color};
      background:#f8f9fa;
      padding:14px 16px;
      margin:12px 0 16px 0;
      border-radius:10px;
    ">
      ${title ? `<div style="font-weight:800;color:#212529;margin-bottom:6px;">${inlineFormat(title)}</div>` : ''}
      <div style="color:#343a40;line-height:1.7;">${inlineFormat(body)}</div>
    </div>
  `;
}

function buildList(items, ordered = false) {
  const tag = ordered ? 'ol' : 'ul';
  return `
    <${tag} style="margin:8px 0 16px 22px;line-height:1.75;color:#343a40;">
      ${items.map(item => `<li style="margin-bottom:6px;">${inlineFormat(item)}</li>`).join('')}
    </${tag}>
  `;
}

function renderHeading(level, text) {
  const styles = {
    1: 'font-size:26px;color:#0d6efd;margin:18px 0 12px;font-weight:800;',
    2: 'font-size:21px;color:#0d6efd;margin:18px 0 10px;font-weight:800;',
    3: 'font-size:18px;color:#343a40;margin:16px 0 8px;font-weight:800;',
    4: 'font-size:16px;color:#495057;margin:14px 0 8px;font-weight:700;'
  };
  return `<h${level} style="${styles[level] || styles[4]}">${inlineFormat(text)}</h${level}>`;
}

function isTableLine(line) {
  return line.includes('|') && !/^```/.test(line);
}

function buildTable(rows) {
  if (!rows.length) return '';
  const headers = rows[0].map(c => c.trim());
  const bodyRows = rows.slice(1);
  return `
    <table style="width:100%;border-collapse:collapse;margin:14px 0 18px 0;font-size:14px;">
      <thead><tr>${headers.map(h => `<th style="text-align:left;padding:10px 12px;border-bottom:2px solid #dee2e6;background:#f8f9fa;">${inlineFormat(h)}</th>`).join('')}</tr></thead>
      <tbody>${bodyRows.map(row => `<tr>${row.map(cell => `<td style="padding:10px 12px;border-bottom:1px solid #e9ecef;vertical-align:top;">${inlineFormat(cell.trim())}</td>`).join('')}</tr>`).join('')}</tbody>
    </table>
  `;
}

function splitLongBulletIntoItems(bulletText) {
  // Busca múltiples menciones de máquina en un solo párrafo y las separa en callouts individuales
  const pattern = /(?:^|[-•])\s*(?:máquina\s*:?\s*)?([^,:]+?)\s*,\s*(?:responsable\s*:?\s*([^,:]+?))\s*(?:[,.]|$)\s*(.*)/gi;
  const items = [];
  let match;
  while ((match = pattern.exec(bulletText)) !== null) {
    const maquina = match[1]?.trim();
    const responsable = match[2]?.trim();
    const resto = match[3]?.trim();
    if (maquina && responsable) {
      items.push({
        title: `Máquina: ${maquina} | Responsable: ${responsable}`,
        body: resto || ''
      });
    }
  }
  if (items.length === 0) {
    // Si no encontró el patrón, dejamos la línea como estaba
    return [bulletText];
  }
  return items;
}

function parseMarkdown(md) {
  const lines = cleanMarkdown(md).split('\n');
  let html = '';
  let paragraph = [];
  let bulletItems = [];
  let orderedItems = [];
  let blockquote = [];
  let tableLines = [];

  const flushParagraph = () => {
    if (!paragraph.length) return;
    const text = paragraph.join(' ').trim();
    if (text) {
      html += `<p style="margin:0 0 12px 0;line-height:1.75;color:#343a40;">${inlineFormat(text)}</p>`;
    }
    paragraph = [];
  };

  const flushBullets = () => {
    if (!bulletItems.length) return;
    for (const item of bulletItems) {
      // Intentar dividir bullets largos en callouts
      if (item.length > 120 && (item.toLowerCase().includes('máquina') || item.toLowerCase().includes('responsable'))) {
        const parts = splitLongBulletIntoItems(item);
        if (typeof parts[0] === 'string') {
          // No se pudo dividir, se trata como bullet normal
          html += buildList([item]);
        } else {
          parts.forEach(p => {
            html += buildCallout(p.title, p.body, '#0d6efd');
          });
        }
      } else {
        html += buildList([item]);
      }
    }
    bulletItems = [];
  };

  const flushOrdered = () => {
    if (!orderedItems.length) return;
    html += buildList(orderedItems, true);
    orderedItems = [];
  };

  const flushBlockquote = () => {
    if (!blockquote.length) return;
    html += `
      <div style="border-left:4px solid #0d6efd;background:#f8f9fa;padding:12px 16px;margin:12px 0 16px 0;border-radius:8px;color:#495057;">
        ${blockquote.map(line => `<div style="margin:4px 0;">${inlineFormat(line)}</div>`).join('')}
      </div>
    `;
    blockquote = [];
  };

  const flushTable = () => {
    if (tableLines.length < 2) {
      tableLines = [];
      return;
    }
    let rows = tableLines
      .map(line => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|'))
      .map(cells => cells.map(c => c.trim()));

    if (rows.length >= 2 && /^\|?(\s*:?-{3,}:?\s*\|)+\s*$/.test(tableLines[1].trim())) {
      rows.splice(1, 1);
    }
    html += buildTable(rows);
    tableLines = [];
  };

  const flushAll = () => {
    flushParagraph();
    flushBullets();
    flushOrdered();
    flushBlockquote();
    flushTable();
  };

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = rawLine.trim();

    if (!line) {
      flushAll();
      continue;
    }

    if (/^---+$/.test(line)) {
      flushAll();
      html += '<hr style="border:none;border-top:1px solid #dee2e6;margin:18px 0;">';
      continue;
    }

    const heading = line.match(/^(#{1,4})\s+(.*)$/);
    if (heading) {
      flushAll();
      const level = heading[1].length;
      html += renderHeading(level, heading[2].trim());
      continue;
    }

    // Callout ya formateado
    const kvBullet = line.match(/^[-*•]\s+\*\*(.+?)\*\*:\s*(.+)$/);
    if (kvBullet) {
      flushAll();
      html += buildCallout(kvBullet[1], kvBullet[2], '#0d6efd');
      continue;
    }

    const simpleBulletKv = line.match(/^[-*•]\s+([^:]+):\s*(.+)$/);
    if (simpleBulletKv && simpleBulletKv[1].length < 50) {
      flushAll();
      html += buildCallout(simpleBulletKv[1], simpleBulletKv[2], '#6c757d');
      continue;
    }

    // Tablas
    if (isTableLine(line)) {
      flushParagraph();
      flushBullets();
      flushOrdered();
      flushBlockquote();
      tableLines.push(rawLine);
      const next = lines[i + 1] ? lines[i + 1].trim() : '';
      if (!isTableLine(next) || !next) {
        flushTable();
      }
      continue;
    }

    // Citas
    if (/^>\s?/.test(line)) {
      flushParagraph();
      flushBullets();
      flushOrdered();
      blockquote.push(line.replace(/^>\s?/, ''));
      const next = lines[i + 1] ? lines[i + 1].trim() : '';
      if (!/^>\s?/.test(next)) {
        flushBlockquote();
      }
      continue;
    }

    // Viñetas
    const bullet = line.match(/^[-*•]\s+(.*)$/);
    if (bullet) {
      flushParagraph();
      flushOrdered();
      flushBlockquote();
      bulletItems.push(bullet[1].trim());
      const next = lines[i + 1] ? lines[i + 1].trim() : '';
      if (!/^[-*•]\s+/.test(next)) {
        flushBullets();
      }
      continue;
    }

    // Numeradas
    const ordered = line.match(/^\d+\.\s+(.*)$/);
    if (ordered) {
      flushParagraph();
      flushBullets();
      flushBlockquote();
      orderedItems.push(ordered[1].trim());
      const next = lines[i + 1] ? lines[i + 1].trim() : '';
      if (!/^\d+\.\s+/.test(next)) {
        flushOrdered();
      }
      continue;
    }

    // Párrafo normal
    flushBullets();
    flushOrdered();
    flushBlockquote();
    paragraph.push(line);
  }

  flushAll();
  return html;
}

