const raw = $input.first().json.output || $input.first().json.text || '';
const maxTelegram = 4096;

// Limpiar Markdown residual
const limpio = raw
  .replace(/^#{1,6}\s/gm, '')       // quitar encabezados (#)
  .replace(/\*\*(.*?)\*\*/g, '$1')  // quitar negritas
  .replace(/\*(.*?)\*/g, '$1')      // quitar cursivas
  .replace(/`{1,3}/g, '')           // quitar backticks
  .replace(/\n{3,}/g, '\n\n')       // normalizar saltos de línea múltiples
  .replace(/^\s*[-•]\s/gm, '- ')    // unificar viñetas
  .trim();

// Truncar si excede el límite de Telegram
const final = limpio.length > maxTelegram
  ? limpio.substring(0, maxTelegram - 3) + '...'
  : limpio;

return [{ json: { mensaje: final } }];
